CREATE TABLE IF NOT EXISTS agent_configs (kind TEXT NOT NULL, recruiter_id TEXT NOT NULL DEFAULT 'global', value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(kind,recruiter_id));
CREATE TABLE IF NOT EXISTS candidate_events (id INTEGER PRIMARY KEY, device_code TEXT NOT NULL DEFAULT '', customer_id TEXT NOT NULL, nickname TEXT NOT NULL DEFAULT '', event_type TEXT NOT NULL DEFAULT 'invited', event_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', interview_date TEXT NOT NULL DEFAULT '', interview_time TEXT NOT NULL DEFAULT '', factory_name TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', district TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'invited', remind_count INTEGER NOT NULL DEFAULT 0, disqualified_reason TEXT NOT NULL DEFAULT '', data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS old_friend_records (id INTEGER PRIMARY KEY, account TEXT NOT NULL DEFAULT '', customer_id TEXT NOT NULL, nickname TEXT NOT NULL DEFAULT '', device_code TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'released', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluation_runs (id INTEGER PRIMARY KEY, device_code TEXT NOT NULL DEFAULT '', eval_date TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, invited INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
